import{_ as i,r as e,o as c,c as l,e as t,a as s,d as n,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Storage - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuration","slug":"configuration","link":"#configuration","children":[{"level":4,"title":"The Local Driver","slug":"the-local-driver","link":"#the-local-driver","children":[]},{"level":4,"title":"Other Driver Prerequisites","slug":"other-driver-prerequisites","link":"#other-driver-prerequisites","children":[]}]},{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[{"level":3,"title":"Obtaining Disk Instances","slug":"obtaining-disk-instances","link":"#obtaining-disk-instances","children":[]},{"level":3,"title":"Retrieving Files","slug":"retrieving-files","link":"#retrieving-files","children":[{"level":4,"title":"File Meta Information","slug":"file-meta-information","link":"#file-meta-information","children":[]}]},{"level":3,"title":"Storing Files","slug":"storing-files","link":"#storing-files","children":[{"level":4,"title":"Prepending / Appending to Files","slug":"prepending-appending-to-files","link":"#prepending-appending-to-files","children":[]}]},{"level":3,"title":"Deleting Files","slug":"deleting-files","link":"#deleting-files","children":[]},{"level":3,"title":"Directories","slug":"directories","link":"#directories","children":[{"level":4,"title":"Get All Files Within a Directory","slug":"get-all-files-within-a-directory","link":"#get-all-files-within-a-directory","children":[]},{"level":4,"title":"Get All Directories Within a Directory","slug":"get-all-directories-within-a-directory","link":"#get-all-directories-within-a-directory","children":[]},{"level":4,"title":"Create a Directory","slug":"create-a-directory","link":"#create-a-directory","children":[]},{"level":4,"title":"Delete a Directory","slug":"delete-a-directory","link":"#delete-a-directory","children":[]}]}]}],"relativePath":"4.x/extend/services/storage.md","filePath":"4.x/extend/services/storage.md"}'),d={name:"4.x/extend/services/storage.md"};function u(g,a,k,h,f,m){const o=e("pre-heading"),p=e("post-heading");return c(),l("div",null,[t(o),a[0]||(a[0]=s("h1",null,"Storage",-1)),t(p),a[1]||(a[1]=s("p",null,[n("October CMS provides a powerful filesystem abstraction thanks to Laravel and the wonderful "),s("a",{href:"https://github.com/thephpleague/flysystem",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Flysystem"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(" PHP package. The Flysystem integration provides simple to use drivers for working with local filesystems and Amazon S3. Even better, it's amazingly simple to switch between these storage options as the API remains the same for each system.")],-1)),a[2]||(a[2]=r(`<h2 id="configuration"><a href="#configuration" class="header-anchor">#</a> Configuration</h2><p>The filesystem configuration file is located at <code>config/filesystems.php</code>. Within this file you may configure all of your &quot;disks&quot;. Each disk represents a particular storage driver and storage location. Example configurations for each supported driver is included in the configuration file. So, simply modify the configuration to reflect your storage preferences and credentials.</p><p>Of course, you may configure as many disks as you like, and may even have multiple disks that use the same driver.</p><h4 id="the-local-driver"><a href="#the-local-driver" class="header-anchor">#</a> The Local Driver</h4><p>When using the <code>local</code> driver, note that all file operations are relative to the <code>root</code> directory defined in your configuration file. By default, this value is set to the <code>storage/app</code> directory. Therefore, the following method would store a file in <code>storage/app/file.txt</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;local&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.txt&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Contents&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="other-driver-prerequisites"><a href="#other-driver-prerequisites" class="header-anchor">#</a> Other Driver Prerequisites</h4><p>Before using the S3 driver, you will need to install the Flysystem S3 package via the Composer package manager.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require league/flysystem-aws-s3-v3 <span class="token string">&quot;^3.0&quot;</span>
</code></pre></div><p>The S3 driver configuration information is located in your <code>config/filesystems.php</code> configuration file. This file contains an example configuration array for an S3 driver. You are free to modify this array with your own S3 configuration and credentials.</p><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><h3 id="obtaining-disk-instances"><a href="#obtaining-disk-instances" class="header-anchor">#</a> Obtaining Disk Instances</h3><p>The <code>Storage</code> facade may be used to interact with any of your configured disks. For example, you may use the <code>put</code> method on the facade to store an avatar on the default disk. If you call methods on the <code>Storage</code> facade without first calling the <code>disk</code> method, the method call will automatically be passed to the default disk:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span>
    <span class="token string single-quoted-string">&#39;avatars/&#39;</span><span class="token operator">.</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
    <span class="token function">file_get_contents</span><span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getRealPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When using multiple disks, you may access a particular disk using the <code>disk</code> method on the <code>Storage</code> facade. Of course, you may continue to chain methods to execute methods on the disk:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$disk</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;local&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span>
</code></pre></div><h3 id="retrieving-files"><a href="#retrieving-files" class="header-anchor">#</a> Retrieving Files</h3><p>The <code>get</code> method may be used to retrieve the contents of a given file. The raw string contents of the file will be returned by the method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>exists</code> method may be used to determine if a given file exists on the disk:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$exists</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="file-meta-information"><a href="#file-meta-information" class="header-anchor">#</a> File Meta Information</h4><p>The <code>size</code> method may be used to get the size of the file in bytes:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$size</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>lastModified</code> method returns the UNIX timestamp of the last time the file was modified:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$time</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">lastModified</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="storing-files"><a href="#storing-files" class="header-anchor">#</a> Storing Files</h3><p>The <code>put</code> method may be used to store a file on disk. You may also pass a PHP <code>resource</code> to the <code>put</code> method, which will use Flysystem&#39;s underlying stream support. Using streams is greatly recommended when dealing with large files:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">,</span> <span class="token variable">$contents</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">,</span> <span class="token variable">$resource</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>copy</code> method may be used to copy an existing file to a new location on the disk:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">copy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;old/file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;new/file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>move</code> method may be used to move an existing file to a new location:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">move</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;old/file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;new/file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="prepending-appending-to-files"><a href="#prepending-appending-to-files" class="header-anchor">#</a> Prepending / Appending to Files</h4><p>The <code>prepend</code> and <code>append</code> methods allow you to easily insert content at the beginning or end of a file:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">prepend</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.log&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Prepended Text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">append</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.log&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Appended Text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="deleting-files"><a href="#deleting-files" class="header-anchor">#</a> Deleting Files</h3><p>The <code>delete</code> method accepts a single filename or an array of files to remove from the disk:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;file2.jpg&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="directories"><a href="#directories" class="header-anchor">#</a> Directories</h3><h4 id="get-all-files-within-a-directory"><a href="#get-all-files-within-a-directory" class="header-anchor">#</a> Get All Files Within a Directory</h4><p>The <code>files</code> method returns an array of all of the files in a given directory. If you would like to retrieve a list of all files within a given directory including all sub-directories, you may use the <code>allFiles</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$files</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">files</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$files</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">allFiles</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="get-all-directories-within-a-directory"><a href="#get-all-directories-within-a-directory" class="header-anchor">#</a> Get All Directories Within a Directory</h4><p>The <code>directories</code> method returns an array of all the directories within a given directory. Additionally, you may use the <code>allDirectories</code> method to get a list of all directories within a given directory and all of its sub-directories:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$directories</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">directories</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Recursive...</span>
<span class="token variable">$directories</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">allDirectories</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="create-a-directory"><a href="#create-a-directory" class="header-anchor">#</a> Create a Directory</h4><p>The <code>makeDirectory</code> method will create the given directory, including any needed sub-directories:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">makeDirectory</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="delete-a-directory"><a href="#delete-a-directory" class="header-anchor">#</a> Delete a Directory</h4><p>Finally, the <code>deleteDirectory</code> may be used to remove a directory, including all of its files, from the disk:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">deleteDirectory</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,52))])}const x=i(d,[["render",u]]);export{y as __pageData,x as default};
